const i={ui:{fig:"Рис. 3",title:"Уголки «треугольником»",svgLabel:"Изометрический рисунок того, как делаются уголки «треугольником»: сумка стачана по бокам и по дну, каждый нижний уголок раскрыт в треугольник так, что боковой шов лёг на шов дна, поперёк него на половине ширины дна от конца шва намечена и прострочена линия, кончик срезан с небольшим припуском, сумка вывернута — дно ровное.",prev:"Предыдущий шаг",dot:(t,e)=>t?`Шаг ${t}: ${e}`:e,start:"Шаги →",next:"Дальше →",overview:"Обзор",stepOf:(t,e)=>`Шаг ${t} из ${e}`,machine:t=>`Машина: ${t.toLowerCase()}`,inThisStep:"В этом шаге",takeApart:"Поставить",putTogether:"Показать дно",replay:"↻ Повторить",parts:"Детали",allSteps:"Пошаговая инструкция",endView:"ВИД С ТОРЦА"},stitches:{straight:"Прямая строчка"},labels:{rightSides:"лицом к лицу",sidesBottom:"бока и дно",aPouch:"плоский мешок",standUp:"поставить вверх дном",openCorner:"раскрыть уголок",seamOnSeam:"шов на шов",triangle:"треугольник",seamEnd:"конец шва",halfBase:"на половине ширины дна",baseWidth:"ширина дна",sewLine:"прострочить по линии",backstitch:"закрепка",bothCorners:"оба уголка",trimTip:"срезать кончик",smallAllowance:"небольшой припуск",turnOut:"вывернуть на лицо",flatBottom:"ровное дно",cornerSeam:"шов уголка"},steps:[{title:"Уголки «треугольником»",text:"Дно сумки, сумка перевёрнута: ровное дно, шов дна посередине, а на каждом конце — короткий шов поперёк, там, где с ним встречается боковой шов. Нажмите на сумку, чтобы её поставить."},{title:"Стачать сумку",text:"Сложите перед и спинку лицом к лицу и стачайте бока и дно: получится плоский мешок, из уголков ничего не вырезано.",details:["Сложите перед и спинку лицом к лицу и сколите зажимами.","Стачайте оба бока и дно.","Из уголков ничего не вырезают: дно получится в следующих шагах.","Если сумка — одна деталь, сложенная по дну, шва дна нет: тогда боковой шов кладут на сгиб дна."]},{title:"Раскрыть уголок",text:"Разведите перед и спинку в нижнем уголке и расправьте его так, чтобы боковой шов лёг точно на шов дна: уголок становится треугольником.",details:["Разведите перед и спинку в одном нижнем уголке.","Расправьте уголок так, чтобы боковой шов лёг точно на шов дна (или на сгиб дна).","Теперь уголок — треугольник, шов идёт по его середине до конца шва у вершины.","Так же раскройте второй нижний уголок.","На рисунке сумка стоит вверх дном, на открытом верхе, чтобы были видны оба уголка."]},{title:"Наметить линию",text:"Наметьте линию поперёк треугольника, под прямым углом к шву, на половине ширины дна от конца шва. Тогда длина линии равна ширине дна.",details:["Решите, каким широким будет дно: это ширина дна.","Отмерьте по шву половину ширины дна от конца шва — там, где строчки сходятся у вершины, — а не от кончика ткани.","Проведите там линию поперёк треугольника, под прямым углом к шву. Её длина равна ширине дна.","Чем дальше линия от вершины, тем шире дно. Так же наметьте второй уголок."]},{title:"Прострочить по линии",text:"Прострочите по намеченной линии, с закрепкой в начале и в конце.",details:["Прострочите по линии от одного края треугольника до другого.","В начале и в конце сделайте закрепку, чтобы шов держался.","Так же прострочите второй уголок."]},{title:"Срезать кончик",text:"Срежьте кончик каждого треугольника, оставив за строчкой небольшой припуск.",details:["Срежьте кончик вдоль строчки, оставив небольшой припуск.","Не задевайте строчку.","Так же сделайте все нижние уголки — и уголки подкладки, если у сумки есть подкладка."]},{title:"Вывернуть",text:"Выверните сумку на лицо: дно ровное, на каждом конце — короткий шов уголка поперёк.",details:["Выверните сумку на лицо и выправьте уголки.","Дно ровное, его ширина равна длине линии поперёк. На каждом конце боковой шов приходит в середину шва уголка."]}],legend:[{title:"Дно",text:"ровное · его ширина равна длине швов уголков"},{title:"Шов дна",text:"соединяет перед и спинку · идёт по середине дна"},{title:"Швы уголков",text:"прострочены поперёк уголка, на половине ширины дна от конца шва"},{title:"Боковые швы",text:"каждый приходит в середину шва уголка"}]};export{i as default};
